def source(id,name,url,kind='supplier',date=None,locator='',access='page_read',note=''):
 sources.append(dict(id=id,publisher=name,url=url,source_type=kind,published_date=date,retrieved_date='2026-10-16',location='Kathmandu Valley / Nepal',locator=locator,access_status=access,note=note))
def rate(id,sid,label,lo,hi,unit,basis,note='',qualifier='range',availability='not_confirmed'):
 f=Decimal('0.09290304') if unit=='ft2' else Decimal('0.3048') if unit=='ft' else None
 norm=None if f is None else dict(unit='m2' if unit=='ft2' else 'm',low=str((Decimal(str(lo))/f).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)) if lo is not None else None,high=str((Decimal(str(hi))/f).quantize(Decimal('.01'),rounding=ROUND_HALF_UP)) if hi is not None else None,factor=str(f))
 obs.append(dict(id=id,source_id=sid,label=label,currency='NPR',low=None if lo is None else str(lo),high=None if hi is None else str(hi),unit=unit,basis=basis,price_qualifier=qualifier,availability=availability,vat_status='not_stated',retrieved_date='2026-10-16',normalized_si=norm,qualification=note))
