assert set(mapping)=={x['id'] for x in d['line_items']}
rows=[]
for x in d['line_items']:
 refs,state,note=mapping[x['id']]
 rows.append(dict(item_id=x['id'],section_id=x['section_id'],section_name=x['section_name'],title=titles[x['id']],description=x['description'],source_page=x['source']['page'],original=dict(quantity=x['quantity'],unit=x['unit_raw'],rate=x['rate'],amount=x['amount'],currency=d['currency']),reference_ids=refs,research_state=state,qualification=note,exact_scope_verified=False,accepted_market_rate=None))
allowances=[dict(section_id='laminate-flooring',state='quote_needed',note='Summary amount only; floor area, product thickness and installed scope absent. No unit rate or market total derived.'),dict(section_id='electrical',state='quote_needed',note='Summary allowance only; circuits, cable quantities, boards and point schedule absent. No whole-package price inferred.')]
counts=dict(collections.Counter(x['research_state'] for x in rows))
register=dict(schema_version='1.0.0',version='v4',title='Kathmandu public rate research for the 51 original Pilates items',as_of='2026-10-16',locale='en-IN',market_currency='NPR',estimate_currency=d['currency'],policy=['Original estimate and SI values remain unchanged.','Public references are not quotations for the exact design. No arbitrary midpoint or market grand total is produced.','Material-only, labour-only, retail and installed scope remain distinct.','Each-to-area and fabric-length-to-area conversions are prohibited without dimensions.','Unknown VAT and current availability stay unknown. Historical and indexed-only prices are labeled.','V5 comparison charts and V6 item imagery have not been created.'],coverage=dict(items=51,items_with_numeric_reference=sum(bool(x['reference_ids']) for x in rows),items_without_numeric_reference=sum(not x['reference_ids'] for x in rows),exact_scope_quotes=0,source_count=len(sources),observation_count=len(obs),states=counts),sources=sources,observations=obs,items=rows,summary_only_areas=allowances)
(BASE/'market-rates.json').write_text(json.dumps(register,ensure_ascii=False,indent=2)+'\n')
(BASE/'items-research.jsonl').write_text('\n'.join(json.dumps(x,ensure_ascii=False) for x in rows)+'\n')
with (BASE/'rate-research.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['item_id','area','title','research_state','reference_ids','exact_scope_verified','accepted_market_rate','qualification'])
 for x in rows:w.writerow([x['item_id'],x['section_name'],x['title'],x['research_state'],';'.join(x['reference_ids']),False,'',x['qualification']])
db=BASE/'rates.sqlite';db.unlink(missing_ok=True);con=sqlite3.connect(db)
con.executescript('CREATE TABLE sources(id TEXT PRIMARY KEY, publisher TEXT, url TEXT, evidence_json TEXT); CREATE TABLE observations(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),low TEXT,high TEXT,unit TEXT,basis TEXT,evidence_json TEXT); CREATE TABLE items(item_id TEXT PRIMARY KEY,section_id TEXT,title TEXT,research_state TEXT,accepted_market_rate TEXT,exact_scope_verified INTEGER CHECK(exact_scope_verified=0),record_json TEXT); CREATE TABLE item_references(item_id TEXT REFERENCES items(item_id),reference_id TEXT REFERENCES observations(id),PRIMARY KEY(item_id,reference_id));')
for x in sources:con.execute('INSERT INTO sources VALUES(?,?,?,?)',(x['id'],x['publisher'],x['url'],json.dumps(x)))
for x in obs:con.execute('INSERT INTO observations VALUES(?,?,?,?,?,?,?)',(x['id'],x['source_id'],x['low'],x['high'],x['unit'],x['basis'],json.dumps(x)))
for x in rows:
 con.execute('INSERT INTO items VALUES(?,?,?,?,?,?,?)',(x['item_id'],x['section_id'],x['title'],x['research_state'],None,0,json.dumps(x)))
 for ref in x['reference_ids']:con.execute('INSERT INTO item_references VALUES(?,?)',(x['item_id'],ref))
con.commit();(BASE/'rates.sql').write_text('\n'.join(con.iterdump())+'\n');con.close()
print(json.dumps(register['coverage']))
